export function applyPositionPolicy(decision,confirmationScoreActual,config=DEFAULT_POSITION_POLICY){
  let positionSizePct=Number(decision.positionSizePct||100),suggestedAction='WAIT';
  if(decision.state==='EARLY_ENTRY'){positionSizePct=config.earlyPct;suggestedAction='BUY_PARTIAL';}
  else if(decision.state==='PULLBACK_ENTRY'){
    if(confirmationScoreActual>=config.fullConfirmationMin){positionSizePct=100;suggestedAction='BUY';}
    else if(confirmationScoreActual>=config.mediumConfirmationMin){positionSizePct=config.mediumConfirmationPct;suggestedAction='BUY_PARTIAL';}
    else {positionSizePct=config.lowConfirmationPct;suggestedAction='BUY_PARTIAL';}
  }else if(decision.state==='BREAKOUT_ENTRY'){
    if(confirmationScoreActual>=config.breakoutFullConfirmationMin){positionSizePct=100;suggestedAction='BUY';}
    else if(confirmationScoreActual>=config.mediumConfirmationMin){positionSizePct=config.mediumConfirmationPct;suggestedAction='BUY_PARTIAL';}
    else {positionSizePct=config.lowConfirmationPct;suggestedAction='BUY_PARTIAL';}
  }else if(['BUY_NOW','BUY_CANDIDATE','SECOND_ENTRY_CANDIDATE'].includes(decision.state))suggestedAction=decision.state==='BUY_NOW'?'BUY':'WATCH';
  else if(decision.state==='RULE_WATCH'||decision.state==='SECONDARY_WATCH')suggestedAction='WATCH';
  return {...decision,positionSizePct,suggestedAction};
}

export function normalizeDecisionReasons(stateReasons=[],missingConditions=[]){
  const reasons=[...new Set(stateReasons.filter(Boolean))],reasonSet=new Set(reasons);
  return {stateReasons:reasons,missingConditions:[...new Set(missingConditions.filter(code=>code&&!reasonSet.has(code)))]};
}

